CREATE DATABASE IF NOT EXISTS landslide_tracker;
USE landslide_tracker;
DROP TABLE IF EXISTS incidents;
CREATE TABLE incidents(
 id INT PRIMARY KEY AUTO_INCREMENT, location VARCHAR(150) NOT NULL,state VARCHAR(100) NOT NULL,district VARCHAR(100) NOT NULL,
 latitude DECIMAL(10,6),longitude DECIMAL(10,6),incident_date DATE NOT NULL,incident_time TIME,risk ENUM('High','Medium','Low') NOT NULL,
 status VARCHAR(40) NOT NULL,rainfall DECIMAL(8,2),affected_area DECIMAL(8,2),affected_people INT DEFAULT 0,road_status VARCHAR(100),
 description TEXT,source VARCHAR(150) DEFAULT 'Demo Project Dataset',last_updated TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);

